#include <stdio.h>

struct Mark { int roll; int score; };

int main(void)
{
    struct Mark record = {7, 60};
    struct Mark *pointer = &record;
    pointer->score += 5;
    printf("%d %d\n", pointer->roll, record.score);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Mark { int roll; int score; };

int main(void)
{
    struct Mark *owner = malloc(2 * sizeof *owner);
    if (owner == NULL) {
        return 1;
    }
    owner[0] = (struct Mark){1, 50};
    owner[1] = (struct Mark){2, 75};
    struct Mark *view = owner + 1;
    view->score = 80;
    printf("%d %d\n", owner[0].score, owner[1].score);
    free(owner);
    return 0;
}

#include <stdio.h>

struct View { int *data; size_t count; };

int main(void)
{
    int marks[] = {10, 20};
    struct View first = {marks, 2};
    struct View second = first;
    second.data[0] = 99;
    printf("%d %d\n", first.data[0], second.data[0]);
    return 0;
}

